def sha256(data: bytes)->str: return hashlib.sha256(data).hexdigest()
def apply_generic_hold_core(stock_hfb: bytes)->bytes:
    if len(stock_hfb)!=STOCK_SIZE: raise PatchReject(f"wrong stock size: {len(stock_hfb)}")
    got=sha256(stock_hfb)
    if got!=STOCK_SHA256: raise PatchReject(f"stock SHA mismatch: {got}")
    out=bytearray(stock_hfb)
    for off,old,new in PATCHES:
        actual=bytes(out[off:off+len(old)])
        if actual!=old:
            raise PatchReject(f"patch precondition failed at 0x{off:X}")
        out[off:off+len(new)]=new
    return bytes(out)
